const DICT = {en: EN, it: IT};
let lang = detect();

function detect() {
    try {
        const saved = localStorage.getItem('on_lang');
        if (UI_LANGS.includes(saved)) return saved;
    } catch (e) { /* storage blocked */ }
    const nav = (navigator.language || 'en').slice(0, 2).toLowerCase();
    return UI_LANGS.includes(nav) ? nav : 'en';
}

export function getLang() {
    return lang;
}

export function setLang(l) {
    if (!UI_LANGS.includes(l)) return;
    lang = l;
    document.documentElement.lang = l;
    try {
        localStorage.setItem('on_lang', l);
    } catch (e) { /* storage blocked */ }
}

export function t(key, vars) {
    let s = (DICT[lang] && DICT[lang][key]) ?? EN[key] ?? key;
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.split('{' + k + '}').join(String(v));
    return s;
}

document.documentElement.lang = lang;
